"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["48470"],{11286(e){e.exports=JSON.parse('{"id":"V4-189","slug":"securities-and-exchange-commission","term":"Securities and Exchange Commission (SEC)","also_known_as":[],"difficulty":"Beginner","definition":"The Securities and Exchange Commission (SEC) is the US federal agency responsible for regulating securities markets, protecting investors and enforcing securities laws.","explanation":["The SEC was created by the Securities Exchange Act of 1934, following the 1929 stock market crash and the Great Depression, to restore confidence in markets.","Its main responsibilities include requiring public companies to disclose accurate financial and other information to investors; regulating stock exchanges, brokers, investment advisers and mutual funds; overseeing the registration of securities offerings; and investigating and bringing civil enforcement actions against insider trading, accounting fraud and other violations.","The SEC is led by five commissioners appointed by the US President and confirmed by the Senate, with no more than three from the same political party. One commissioner serves as chair.","For example, a company planning to go public in the United States must file a registration statement with the SEC disclosing its financial results, risks and business, and then file regular reports, such as annual and quarterly reports, once listed.","The SEC works alongside other bodies, such as FINRA, a self-regulatory organisation for brokers, and the Commodity Futures Trading Commission, which regulates most derivatives. The SEC\u2019s approach to newer areas, such as crypto assets, has changed significantly with different leadership."],"note":"","total":1725,"prev":{"slug":"secured-debt","term":"Secured Debt"},"next":{"slug":"securities-lending","term":"Securities Lending"}}')}}]);